import {athleticBuild} from './rider-appearance.js';
import {batchRigidDetails} from './rigid-details.js?v=detail18';
import * as T from './three.module.js';
import {hashSeed} from './resident-ai.js';
// Children and elders have independently built proportions, faces and clothing.
export function createAgeRig(person,key){const seed=hashSeed(key),elder=person.role==='elder',girl=person.variant==='lady',root=new T.Group(),model=new T.Group();root.add(model);root.name=elder?'Elder resident':'Child resident';const skin=['#b17b54','#d3a17d','#875b42','#d0ac88'][seed%4],hair=elder?'#b8b6aa':['#3d2a20','#705038','#262626'][seed%3],shirt=['#cb9a55','#678ca5','#9a6c89','#718c68','#ba715c'][seed%5],pants=elder?'#5a6059':girl?'#667d98':'#596d85',arms=[],legs=[];
 const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.88}),mats=new Map(),material=c=>{if(!mats.has(c))mats.set(c,mat(c));return mats.get(c);};
 function oval(parent,name,c,x,y,z,sx,sy,sz){const m=new T.Mesh(new T.SphereGeometry(1,16,12),material(c));m.name=name;m.position.set(x,y,z);m.scale.set(sx,sy,sz);parent.add(m);return m;}
 function tube(parent,name,c,a,b,r1,r2){const aa=new T.Vector3(...a),bb=new T.Vector3(...b),v=bb.clone().sub(aa),m=new T.Mesh(new T.CylinderGeometry(r2,r1,v.length(),12),material(c));m.name=name;m.position.copy(aa.add(bb).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),v.normalize());parent.add(m);return m;}
 const hip=elder?1.08:.65,shoulder=elder?1.72:1.13,headY=elder?2.03:1.43;oval(model,'Clothed torso',shirt,0,(hip+shoulder)/2,0,elder?.3:.23,(shoulder-hip)*.64,elder?.2:.15);oval(model,'Waistband',pants,0,hip,0,elder?.24:.19,.12,.16);tube(model,'Neck',skin,[0,shoulder-.02,0],[0,headY-.22,0],.095,.09);
 const head=new T.Group();head.position.set(0,headY,elder?.07:.015);model.add(head);oval(head,'Face',skin,0,0,0,elder?.18:.205,elder?.245:.23,.185);oval(head,'Hair cap',hair,0,.15,-.035,.19,.13,.177);
 for(const side of [-1,1]){oval(head,'Ear',skin,side*.19,-.015,0,.04,.065,.045);oval(head,'Eye white','#e7e2d6',side*.073,.02,.167,.043,.026,.021);oval(head,'Iris',['#4d6854','#715437','#444d53'][seed%3],side*.073,.02,.187,.019,.019,.009);oval(head,'Pupil','#202628',side*.073,.021,.194,.009,.012,.005);oval(head,'Brow',hair,side*.075,.078,.166,.05,.012,.014);if(!elder&&girl){oval(head,'Side hair',hair,side*.16,.075,-.10,.055,.17,.08);oval(head,'Pigtail',hair,side*.245,-.035,-.09,.055,.13,.055);oval(head,'Hair band',shirt,side*.21,.02,-.08,.025,.03,.03);}}
 oval(head,'Nose',skin,0,-.035,.187,.037,.045,.05);oval(head,'Mouth','#8c594c',0,-.115,.169,.054,.012,.014);if(elder){for(const side of [-1,1]){const rim=new T.Mesh(new T.TorusGeometry(.067,.008,6,18),material('#514d42'));rim.position.set(side*.079,.022,.203);head.add(rim);oval(head,'Cheek crease','#ab8069',side*.105,-.075,.166,.028,.008,.008);}tube(head,'Glasses bridge','#514d42',[-.013,.025,.204],[.013,.025,.204],.007,.007);oval(head,'Grey side hair',hair,0,-.04,-.13,.19,.16,.07);if(!girl)oval(head,'Moustache',hair,0,-.085,.188,.063,.025,.024);}
 for(const side of [-1,1]){const leg=new T.Group();leg.position.set(side*(elder?.13:.11),hip,0);model.add(leg);const length=hip-.10;tube(leg,'Trouser leg',pants,[0,0,0],[0,-length,0],elder?.12:.09,elder?.085:.065);oval(leg,'Shoe',elder?'#48423a':'#ddcfb0',0,-length,.065,elder?.1:.085,.085,elder?.17:.13);oval(leg,'Sole','#333a3b',0,-length-.045,.07,elder?.104:.089,.035,elder?.175:.135);legs.push(leg);const arm=new T.Group();arm.position.set(side*(elder?.29:.225),shoulder-.07,0);arm.rotation.z=side*.1;model.add(arm);tube(arm,elder?'Cardigan sleeve':'T-shirt sleeve',shirt,[0,0,0],[0,-.19,0],elder?.1:.085,elder?.09:.07);tube(arm,'Forearm',skin,[0,-.17,0],[0,elder?-.62:-.41,.015],elder?.075:.06,elder?.055:.045);oval(arm,'Hand',skin,0,elder?-.66:-.45,.025,.055,.075,.045);arms.push(arm);}
 // Shirt buttons, collar and front pocket give each outfit readable structure.
 for(let i=0;i<3;i++)oval(model,'Button','#ded6bc',0,shoulder-.15-i*.12,elder?.205:.155,.012,.012,.008);tube(model,'Collar left','#e0d6bb',[-.10,shoulder,.12],[0,shoulder-.10,.17],.024,.024);tube(model,'Collar right','#e0d6bb',[.10,shoulder,.12],[0,shoulder-.10,.17],.024,.024);if(elder){const cane=new T.Group();cane.position.set(.39,.82,.12);model.add(cane);tube(cane,'Walking cane','#73563b',[0,-.78,0],[0,.04,0],.019,.019);oval(cane,'Cane grip','#534736',0,.05,.035,.024,.025,.075);model.rotation.x=.07;}
 batchRigidDetails(root); root.userData.age=elder?'elder':'child';root.userData.proportions={height:elder?2.3:1.69,headRadius:elder?.18:.205,legLength:hip-.1};let t=seed%23;return {root,model,mixer:{setTime(v){t=v;}},update(dt,speed=0,task=null){t+=dt*(speed>.05?speed*4.5:1);for(let i=0;i<2;i++){legs[i].rotation.x=speed>.05?Math.sin(t+i*Math.PI)*(elder?.25:.43):0;arms[i].rotation.x=speed>.05?-Math.sin(t+i*Math.PI)*.3:Math.sin(t*.6+i)*.025;}head.rotation.y=Math.sin(t*.32)*.07;model.position.y=speed>.05?Math.abs(Math.sin(t))*.018:0;}};}
export function styleAdult(rig,key){const seed=hashSeed(key),palette=['#68939c','#a17657','#7e8864','#887b9b','#b1a080','#637683'],shirt=palette[seed%palette.length],head=rig.model.getObjectByName('Head');athleticBuild(rig.model,.93+(seed%6)*.055);if(head){head.scale.multiply(new T.Vector3(.91+(seed%5)*.04,.95+(seed%3)*.035,.94+(seed%4)*.03));}rig.model.scale.x*=.9+(seed%7)*.035;rig.model.traverse(o=>{if(!o.isMesh)return;for(const m of Array.isArray(o.material)?o.material:[o.material]){if(/torso|shirt|body|jacket/i.test(o.name)){m.color.set(shirt);m.roughness=.88;}if(/^Skin$/i.test(m.name))m.color.set(['#b17b54','#d3a17d','#875b42','#d0ac88'][seed%4]);if(/pants|trouser/i.test(o.name))m.color.set(['#697573','#62564b','#50657d','#665c72'][seed%4]);if(/hair/i.test(o.name))m.color.set(['#332a22','#6a5037','#a28a5c','#4a403c'][seed%4]);}});rig.root.userData.identitySeed=seed;return rig;}
